// Build Outer Heaven report payload for Grok Watchdog
const body = $json.body || $json;

const reportId = body.reportId || body.id || `oh_${Date.now()}`;
const correlationId = body.correlationId || body.correlation_id || reportId;
const title = body.title || body.subject || 'Outer Heaven Report';
const status = body.status || 'info';
const content = body.content || body.message || body.report || '';
const source = body.source || 'outer-heaven';
const severity = body.severity || body.level || 'normal';

const text = [
  `OUTER HEAVEN REPORT`,
  ``,
  `Title: ${title}`,
  `Status: ${status}`,
  `Severity: ${severity}`,
  `Source: ${source}`,
  content ? `\nDetails:\n${content}` : '',
  ``,
  `ID: ${reportId}`,
  `cid: ${correlationId}`,
  `Time: ${new Date().toISOString()}`
].filter(Boolean).join('\n');

return [{ json: { text, reportId, title, severity, correlationId, status, error: content || null } }];
